def compute(vars):
    net_income = vars["Net Income"]
    revenue = vars["Revenue"]
    multiplier = vars["100"]

    try:
        margin = (net_income / revenue) * multiplier
    except ZeroDivisionError:
        return None

    return {
        "value": margin,
        "trace": {
            "Net Income": net_income,
            "Revenue": revenue,
            "100": multiplier,
            "Net Income / Revenue": net_income / revenue,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
